    @log_method_name
    def fix_mrbts_id(self, path_to_scfc):
        with ta_admin_interface.admin_interface() as admin_client:
            mrbts_id = admin_client.get_managed_objects('MRBTS')[0]['distName'].split('-')[1]

        with open(path_to_scfc) as scfc_file:
            delta_scfc = scfc_file.read()

        new_delta = None
        if not all(int(mrbts_id) == int(i) for i in re.findall(r'MRBTS-(\d*)', delta_scfc)):
            new_delta = re.sub(r'MRBTS-(\d*)', 'MRBTS-{}'.format(mrbts_id), delta_scfc)
        if not all(int(mrbts_id) == int(i) for i in re.findall(r'NRBTS-(\d*)', delta_scfc)):
            new_delta = re.sub(r'NRBTS-(\d*)', 'NRBTS-{}'.format(mrbts_id), new_delta if new_delta else delta_scfc)
        if new_delta:
            with open(path_to_scfc, 'w') as scfc_file:
                scfc_file.write(new_delta)
            logger.console("Changed MRBTS id to {} in delta file: {}".format(mrbts_id, path_to_scfc))

    @saneconsole
    @log_method_name
    def wait_until_all_cells_reach_onair(self, timeout='480', check_only_one_side=True, remote_host=None):
        with ta_admin_interface.admin_interface() as admin_client:
            time_step = 10
            time_start = time.time()
            while time.time() < time_start + int(timeout):
                all_cells_are_online = True
                for cell in admin_client.get_cells_info():
                    if cell['status']['availabilityStatus'] is not None and cell['status']['availabilityStatus'] != '' \
                            and cell['status']['availabilityStatus'].lower() != 'online':
                        all_cells_are_online = False
                if all_cells_are_online:
                    return True
                time.sleep(time_step)

        raise ExecutionFailed(message="Wrong number of cells OnAir!")

    @staticmethod
    @saneconsole
    def __check_commissioning_result(result):
        if result["commissioningResult"]['activationResult']['resultNode']['parameters']['result'] != 'Success':
            logger.debug(json.dumps(result, indent=4))
            raise ExecutionFailed("Commissioning failed")

    @log_method_name
    def find_scfc_and_send_delta_commissioning_retrying_after_errors(self, scfc_filename,
                                                                     error_codes_to_ignore=(27, 69),
                                                                     retries=5,
                                                                     retry_timer=60,
                                                                     remote_host=None):
        """
        This keywords finds delta file for release and sends it.
        In addition, it will retry sending delta if error is AdminApiProcedureFailureException with one of the specified error codes.
        :param scfc_filename: name (with extension) of delta file to be found and send
        :param error_codes_to_ignore: int value found in Exception.error_code attribute.
        By default has values of most common exceptions - 27 corresponding to CPlane is busy/Another CM procedure
        ongoing and 69 corresponding to Operation failed.
        :param retries: max number of times delta file should be send, defaults to 5
        :param retry_timer: time (in seconds) to wait between subsequent retries, defaults to 60
        :return: None
        """
        found_scfc_filepath = self.get_commissioning_file_for_enb_release_name(input_filename=scfc_filename)
        try:
            error_codes_to_ignore = tuple(map(int, error_codes_to_ignore))
        except TypeError:
            error_codes_to_ignore = int(error_codes_to_ignore),
        self._send_delta_commissioning_retrying_after_errors(input_filepath=found_scfc_filepath,
                                                             error_codes_to_ignore=error_codes_to_ignore,
                                                             retries=retries,
                                                             retry_timer=retry_timer,
                                                             remote_host=remote_host)

    @saneconsole
    @log_method_name
    def _send_delta_commissioning_retrying_after_errors(self,
                                                        input_filepath,
                                                        error_codes_to_ignore,
                                                        retries,
                                                        retry_timer,
                                                        remote_host):
        """
        Sends delta commissioning from given file and retries if caught exception with one of the provides
        :param input_filepath: Filepath of delta
        :param error_codes_to_ignore: int value found in Exception.error_code attribute
        :param retries: max number of times delta file should be send
        :param retry_timer: time to wait between subsequent retries
        :return: None
        """
        for i in range(1, int(retries) + 1):
            logger.info('Sending Delta Commissioning', also_console=True)
            try:
                with ta_admin_interface.get_admin_interface(remote_host) as admin_client:
                    response = admin_client.perform_delta_recommissioning(delta_file=input_filepath,
                                                                          skip_parameter_relation_errors=False)
                self.__check_commissioning_result(response)
            except ta_admin_ApiProcedureFailureException as err:
                logger.warn(err)
                logger.info('Delta Commissioning {}/{} failed, retry in {}s'.format(i, retries, retry_timer),
                            also_console=True)
                time.sleep(float(retry_timer))
            except AdminApiProcedureFailureException as err:
                logger.warn(err)
                if err.error_code not in error_codes_to_ignore:
                    raise ExecutionFailed("Not ignored error code {} caught.\nException: {}".format(err.error_code,
                                                                                                    str(err)))
                logger.info('Delta Commissioning {}/{} failed, retry in {}s'.format(i, retries, retry_timer),
                            also_console=True)
                time.sleep(float(retry_timer))
            else:
                break
        else:
            raise ExecutionFailed("Sending delta commissioning failed after {} trials".format(retries))

    @saneconsole
    @log_method_name
    def delete_scf_objects(self, dist_names, skip_parameter_relation_errors=False,
                           should_activate=True, output_dirpath=None, timeout=300):
        """
        Perform object recommissioning, create, update and delete operation can be used.

        :param string or list dist_names: Objects dist names list i.e. "MRBTS-111/LNBTS-40/LNCEL-11/LNRELGNBCELL-0"
        :param boolean skip_parameter_relation_errors: Skip parameter relation errors
        :param bool should_activate: Should automatically activate plan
        :param str output_dirpath: default None (then value of ${OUTPUT_DIR} will be retrieced), different can be provided,
                                   it's a path for saving a copy of created delta file with objects to delete
        :param Union[int,str] timeout: Time to wait for positive procedure result
        :return dict: Recommissioning result

        Example usage:
        Delete Scf Objects     dist_names=['MRBTS-1/NRBTS-1/NRCELLGRP-0', 'MRBTS-1/NRBTS-1/NRCELLGRP-1']
        """
        method_name = inspect.currentframe().f_code.co_name
        logging.warning(WRN_MSG_RELATION_ERRORS + method_name)
        delta = self._create_delta_to_delete_objects(dist_names=dist_names, output_dirpath=output_dirpath)

        with ta_admin_interface.admin_interface() as admin_client:
            admin_client.perform_delta_recommissioning(delta_file=delta, skip_parameter_relation_errors=skip_parameter_relation_errors,
                                                       should_activate=should_activate, timeout=timeout)

    def _create_delta_to_delete_objects(self, dist_names, output_dirpath=None):
        """
        Creates a delta file in output directory
        """
        if isinstance(dist_names, str):
            dist_names = [dist_names]
        delta = []
        for dist_name in dist_names:
            delta.append({'distName': dist_name,
                          'operation': 'delete',
                          'parameters': []})
        delta = json.dumps(delta, indent=4)
        if not output_dirpath:
            output_dirpath = get_robot_output_dir()
        output_delta_path = output_dirpath + "/objects_to_delete.json"
        with open(output_delta_path, 'w') as output_delta_file:
            output_delta_file.write(delta)
        return output_delta_path

