    def get_latest_validation_result_of_delta_plan_aic(self, plan_id, connection):
        timer = 60
        while timer > 0:
            try:
                validation_info = connection.get_latest_validation_result_of_delta_plan(plan_id)
                return validation_info
            except Exception:
                time.sleep(1)
                timer -= 1
                continue
        return "It was not possible to collect validation info"

    def wait_for_activation_of_delta_plan(self, plan_id, operation_id, validation_info, connection):
        timer = 30
        while timer > 0:
            activation_delta_state = connection.get_operation_state_of_activating_delta_plan(
                plan_id=plan_id, operation_id=operation_id)
            if activation_delta_state['status'] == 'success':
                logger.console("Operation state of activating delta plan: {}".format(activation_delta_state['status']))
                return activation_delta_state
            elif activation_delta_state['status'] == 'failure':
                raise Exception("Activating of delta plan failed, validation errors: {}".format(validation_info))
            else:
                time.sleep(1)
                timer -= 1
        logger.console("Operation state of activating delta plan: {}".format(activation_delta_state['status']))
        return activation_delta_state

