    def convert_distname_to_dict(self, dist_name):
        distname = dist_name['distName']
        dict_of_parameters = {}
        for parameter in dist_name['parameters']:
            if isinstance(parameter['value'], list):
                for id, element in enumerate(parameter['value']):
                    for list_parameter, value in element.items():
                        converted_list_param_name = '{}/{}/{}'.format(parameter['parameter_path'], id, list_parameter)
                        dict_of_parameters.update({converted_list_param_name: value})
            else:
                dict_of_parameters.update({parameter['parameter_path']: parameter['value']})
        return {'mo_dn': distname, 'updated_paras_dict': dict_of_parameters, 'operation': dist_name['operation']}

