    def override_vlans_in_scf_vdu(self, input_filepath, output_dirpath, vdu):  # noqa
        output_filepath = self._set_output_file_path(input_filepath, output_dirpath)
        vlans_id_list = self.get_list_of_vlans_id_to_change_in_vdu(vdu)
        if vlans_id_list is None:
            return input_filepath
        ET.register_namespace('', 'raml21.xsd')
        scf = ET.parse(input_filepath)
        root = scf.getroot()
        for raml in root:
            for cell in range(len(vlans_id_list)):
                for managedObject in raml.findall('{raml21.xsd}managedObject'):
                    if managedObject.get('distName') == 'MRBTS-1/MNL-1/MNLENT-1/CELLMAPPING-1/LCELNR-{}'.format(cell + 1):
                        for parameter in managedObject.findall('{raml21.xsd}p'):
                            if parameter.attrib['name'] == 'vlanId':
                                parameter.text = str(vlans_id_list[cell])
                                scf.write(output_filepath)
        return output_filepath

    def override_serialNumberPlanned_and_prodCodePlanned_in_scf_vdu(self, input_filepath, output_dirpath, vdu):  # noqa
        output_filepath = self._set_output_file_path_serial_number(input_filepath, output_dirpath)
        serial_number = self.get_serial_number_from_init(vdu)
        product_code = self.get_product_code_from_init(vdu)
        if serial_number is None:
            return input_filepath
        ET.register_namespace('', 'raml21.xsd')
        scf = ET.parse(input_filepath)
        root = scf.getroot()
        for raml in root:
            for managedObject in root.findall('.//{raml21.xsd}managedObject[@distName="MRBTS-1/EQM-1/APEQM-1/RNICMOD-1"]'):
                for parameter in managedObject.findall('{raml21.xsd}p[@name="serialNumberPlanned"]'):
                    parameter.text = str(serial_number)
                for parameter in managedObject.findall('{raml21.xsd}p[@name="prodCodePlanned"]'):
                    parameter.text = str(product_code)
                    scf.write(output_filepath)
        return output_filepath

