    def send_commissioning_vcu_and_all_vdus(self, scf_vcu, scf_vdu_1, scf_vdu_2=None):
        """
        Keyword allowed to perform full commissioning simultaneously on vcu and vdu (1 or 2) if scfc will be located in default folder
        or in the folder with the name corresponding to the release name, please specify only the name od scfc

         :param string scf_vcu: Name of scfc file for vcu
         :param string scf_vdu_1: Name of scfc file for vdu1
         :param string scf_vdu_2: Name of scfc file for vdu2, default None, should be None if test line has only 1 vdu
        """
        vdu_1 = 1
        vdu_2 = 2
        t1 = threading.Thread(target=self.find_scfc_and_send_full_commissioning_vcu, args=(scf_vcu,))
        t2 = threading.Thread(target=self.find_scfc_and_fix_and_send_full_commissioning_vdu, args=(scf_vdu_1, vdu_1))
        if scf_vdu_2:
            t3 = threading.Thread(target=self.find_scfc_and_fix_and_send_full_commissioning_vdu, args=(scf_vdu_2, vdu_2))
        t1.start()
        t2.start()
        if scf_vdu_2:
            t3.start()
        t1.join()
        t2.join()
        if scf_vdu_2:
            t3.join()

    def send_commissioning_vcu_and_all_vdus_scfc_filepath(self, scf_vcu_filepath, scf_vdu_1_filepath, scf_vdu_2_filepath=None):  # noqa
        """
        Keyword allowed to perform full commissioning simultaneously on vcu and vdu (1 or 2) if you want to use scfc path

         :param scf_vcu_filepath: scfc filepath for vcu
         :param scf_vdu_1_filepath: scfc filepath for vdu1
         :param scf_vdu_2_filepath: scfc filepath for vdu2, default None, should be None if test line has only 1 vdu
        """
        tl_type = self.check_and_return_tl_type()
        vdu_1 = 1
        vdu_2 = 2
        threading.excepthook = self.thread_exception_handling
        t1 = threading.Thread(target=self.perform_commissioning_vcu_aic, args=(scf_vcu_filepath,))
        if tl_type == 'DC':
            t2 = threading.Thread(target=self.fix_serialNumberPlanned_and_prodCodePlanned_and_send_full_commissioning_vdu_with_given_scf_filepath,
                                  args=(scf_vdu_1_filepath, vdu_1))
        else:
            t2 = threading.Thread(target=self.fix_and_send_full_commissioning_vdu_with_given_scf_filepath, args=(scf_vdu_1_filepath, vdu_1))
        if scf_vdu_2_filepath:
            if tl_type == 'DC':
                t3 = threading.Thread(target=self.fix_serialNumberPlanned_and_prodCodePlanned_and_send_full_commissioning_vdu_with_given_scf_filepath,
                                      args=(scf_vdu_2_filepath, vdu_2))
            else:
                t3 = threading.Thread(target=self.fix_and_send_full_commissioning_vdu_with_given_scf_filepath, args=(scf_vdu_2_filepath, vdu_2))
        t1.start()
        t2.start()
        if scf_vdu_2_filepath:
            t3.start()
        t1.join()
        t2.join()
        if scf_vdu_2_filepath is not None:
            t3.join()
        if self.check_exception is not None:
            logger.console(self.check_exception)
            raise Exception

    def thread_exception_handling(self, args):
        self.check_exception = args.exc_value

    def check_and_return_tl_type(self):
        tl = BuiltIn().get_variable_value("${tl}")
        tl_cloud_topology = tl.tl_cloud_topology
        tl_cloud_topology_type = tl_cloud_topology.split('_')[-1]
        if tl_cloud_topology_type == 'DC' or tl_cloud_topology_type == 'SWFH':
            logger.console("Test line topology is: {}".format(tl_cloud_topology))
            return tl_cloud_topology_type
        else:
            try:
                tl.gnbs[0].dus[0].rannics[0].serial_number
                logger.console("Test line topology is: {}, type DC based on tl configuration info".format(tl_cloud_topology))
                return 'DC'
            except Exception:
                logger.console("Test line topology is: {}, type SWFH based on tl configuration info".format(tl_cloud_topology))
                return 'SWFH'

    def download_and_update_bsr_package(self, filepath_url, download_filepath):
        """
        Method used to download and update BeamSet Realization package.

        :param filepath_url: Provided url leading to *.zip BSR package
        :param download_filepath: Download path for a file.
        """
        self.ta5g_file_system.download_bsr_package(filepath_url, download_filepath)
        self.update_software_package(download_filepath)
